def comps4(g,color):
    H,W=len(g),len(g[0]);seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==color and (x,y) not in seen:
